import {auth,db,ADMIN_UID,ref,col,getDoc,getDocFromServer,getDocs,getDocsFromServer,documentId,query,where,onSnapshot,setDoc,updateDoc,deleteDoc,runTransaction,writeBatch,serverTimestamp,Timestamp,onAuthStateChanged,signInWithEmailAndPassword,signOut,saveOrder,readOrder,dayRead,sha,randomHex} from './firebase.js';
import {today,addDays,dayLabel,esc,money,code,grouped,total,priceOf,paidTotal,remaining,status,aggregate,validSummary,csv,effective,dayConfig,ALLERGENS,MAX_UNITS,normal,textClean,merge,localInstant,VERSION,sortedProducts,sortedUnits,productCompare,productCategory,categoryGroups} from './core.js';
const $=x=>document.getElementById(x),main=$('main'),dlg=$('dialog');let master=null,date=today(),dc=null,orders=[],page='home',unsub=null,dayUnsub=null,load=0,undo=null,seen=new Set(),sound=localStorage.getItem('tostada.sound')==='1',isAdmin=false,stream=null,frame=null,working=false,testMode=false;
let filters={zone:'all',status:'all',product:'all',course:'all',group:'all',prepared:'all',q:'',sort:'code',special:false};
const toast=s=>{$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').hidden=true,6000)};
const describe=e=>({'permission-denied':'No tienes permiso para realizar esta operación.','auth/invalid-credential':'Correo electrónico o contraseña incorrectos.','auth/wrong-password':'Correo electrónico o contraseña incorrectos.','auth/user-not-found':'Correo electrónico o contraseña incorrectos.','auth/invalid-email':'Introduce un correo electrónico válido.','auth/user-disabled':'Esta cuenta está desactivada.','auth/too-many-requests':'Demasiados intentos. Espera antes de volver a intentarlo.','auth/network-request-failed':'No se puede conectar. Comprueba tu conexión.','unavailable':'El servicio no está disponible. Inténtalo más tarde.','auth/unauthorized-domain':'No se puede iniciar sesión en este momento. Contacta con el responsable del servicio.','resource-exhausted':'El servicio está ocupado. Inténtalo más tarde.'}[e?.code]||(!e?.code&&e?.name==='Error'?e.message:'No se pudo completar la operación. Inténtalo de nuevo.'));const fail=e=>{console.error('Operación no completada',e);toast(describe(e))};const online=()=>{if(!navigator.onLine)throw Error('Sin conexión. No se guardarán cambios.');};
const action=async(fn,b)=>{if(b)b.disabled=true;try{online();await fn()}catch(e){fail(e)}finally{if(b)b.disabled=false}};
const opt=(value,label,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
function productOptions(d,selected,activeOnly=false){const groups=new Map();for(const [id,p] of sortedProducts(d)){if(activeOnly&&!p.active)continue;const cat=p.category||'Otros';if(!groups.has(cat))groups.set(cat,[]);groups.get(cat).push(opt(id,p.name+' · '+money(p.price),selected))}return [...groups].map(([cat,opts])=>`<optgroup label="${esc(cat)}">${opts.join('')}</optgroup>`).join('')}
function groupedMarkup(rows,d,idOf,render){return categoryGroups(rows,d,idOf).map(([cat,items])=>`<div class="product-category">${esc(cat)}</div>${items.map(render).join('')}`).join('')}
const metrics=arr=>`<div class="grid">${arr.map(([l,v])=>`<div class="metric"><small>${esc(l)}</small><b>${esc(v)}</b></div>`).join('')}</div>`;
const openInfo=(title,html)=>{dlg.innerHTML=`<h2>${esc(title)}</h2>${html}<button id="closeDlg" class="secondary">Cerrar</button>`;if(!dlg.open)dlg.showModal();$('closeDlg').onclick=()=>dlg.close()};
function login(msg=''){isAdmin=false;$('nav').hidden=true;$('logout').hidden=true;$('sync').textContent='Sin sesión';main.innerHTML=`<form id="login" class="card" style="max-width:460px;margin:40px auto"><h1>Iniciar sesión</h1>${msg?`<p class="notice error">${esc(msg)}</p>`:''}<label for="email">Correo electrónico</label><input id="email" type="email" autocomplete="username" autocapitalize="none" spellcheck="false" required><label for="pw">Contraseña</label><input id="pw" type="password" autocomplete="current-password" required><button class="primary" type="submit" style="width:100%;margin-top:12px">Entrar</button><div id="loginError" role="alert" aria-live="polite"></div></form>`;$('login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('loginError').textContent='Conectando…';try{online();await signInWithEmailAndPassword(auth,$('email').value.trim(),$('pw').value)}catch(err){console.error('Inicio de sesión',err);if($('loginError'))$('loginError').textContent=describe(err)}finally{b.disabled=false}}}
function startError(e){console.error('Inicio de gestión',e);$('nav').hidden=true;$('logout').hidden=false;$('sync').textContent='No disponible';main.innerHTML=`<div class="card"><h2>No se pudo iniciar la gestión</h2><p class="notice error">${esc(describe(e))}</p><p>Vuelve a intentarlo. Si el problema continúa, contacta con el responsable del servicio.</p><div class="row"><button id="retry">Reintentar</button><button id="backLogin" class="secondary">Cerrar sesión</button></div></div>`;$('retry').onclick=()=>startAdmin();$('backLogin').onclick=()=>signOut(auth)}
async function startAdmin(){if(auth.currentUser?.uid!==ADMIN_UID)return;isAdmin=true;$('logout').hidden=false;$('nav').hidden=true;$('sync').textContent='Comprobando permisos…';main.innerHTML='<div class="card">Preparando la cafetería…</div>';try{const s=await getDocFromServer(ref('config','main'));if(!s.exists()){setup();return}master=s.data();await refreshDays();await subscribe(date);$('nav').hidden=false;setPage('home');/* Mantenimiento automático se activa tras verificar el procedimiento. */}catch(e){startError(e)}}
let deniedAccount=false;
async function boot(){onAuthStateChanged(auth,async u=>{if(!u){cleanup();login(deniedAccount?'Esta cuenta no tiene acceso a la gestión.':'');deniedAccount=false;return}if(u.uid!==ADMIN_UID){cleanup();deniedAccount=true;try{await signOut(auth)}catch(e){startError(e)}return}await startAdmin()})}
function cleanup(){unsub?.();dayUnsub?.();stopCamera();orders=[];dc=null;master=null;undo=null;isAdmin=false;seen.clear()}
function setup(){ $('sync').textContent='Configuración pendiente';$('nav').hidden=true;main.innerHTML=`<form id="setup" class="card"><h1>Primera configuración</h1><p class="ok">✓ Acceso correcto</p><p>Elige ahora el código que utilizará el alumnado. No existe un código predeterminado.</p><label for="initCode">Código común (mínimo 10 caracteres)</label><input id="initCode" type="text" minlength="10" maxlength="128" required autocomplete="off" placeholder="Elige un código para el centro"><p>Se cargarán 15 productos, cursos, zonas, límite de 3 unidades, antelación de 7 días y horario 11:05–11:35.</p><p class="notice warn">Los pedidos permanecerán cerrados hasta que el servicio esté preparado.</p><button class="primary">Inicializar cafetería</button><div id="setupError" role="alert"></div></form>`;$('setup').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const el=$('setupError');el.textContent='Creando configuración…';try{online();const seed=await fetch('./seed.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('No se puede cargar catálogo inicial.');return r.json()});const value=$('initCode').value.trim();if(value.length<10)throw Error('El código debe tener al menos 10 caracteres.');const hash=await sha(value);await runTransaction(db,async tx=>{const old=await tx.get(ref('config','main'));if(old.exists())return;seed.settings.enabled=false;tx.set(ref('config','main'),{base:seed,changes:[],revision:1});tx.set(ref('config','private'),{hash});});await startAdmin();}catch(err){if($('setupError'))$('setupError').textContent=describe(err);else startError(err)}finally{b.disabled=false}}}
async function refreshDays(){await runTransaction(db,async tx=>{const snap=await tx.get(ref('config','main'));if(!snap.exists())throw Error('Falta configuración inicial.');const m=snap.data();const from=today(),dates=Array.from({length:32},(_,i)=>addDays(from,i));const existing=[];for(const d of dates)existing.push(await tx.get(ref('days',d)));const availability=[];for(let i=0;i<dates.length;i++){const old=existing[i].data(),conf=dayConfig(m,dates[i]);if(old?.archiving||old?.archived)continue;const current=old?.revision===m.revision?old:conf;if(old?.revision!==m.revision)tx.set(ref('days',dates[i]),conf,{merge:true});if(current.open)availability.push({date:dates[i],opensAt:current.opensAt,cutoffAt:current.cutoffAt,editAt:current.editAt});}tx.set(ref('system','status'),{ready:true,revision:m.revision,minVersion:VERSION,publishedFor:from,available:availability,advance:effective(m,from).settings.advance,updatedAt:serverTimestamp()});tx.set(ref('system','access'),{ready:true});master=m});}
async function subscribe(d){date=d;const token=++load;unsub?.();dayUnsub?.();orders=[];dc=null;seen.clear();$('sync').textContent='Cargando…';dayUnsub=onSnapshot(ref('days',d),s=>{if(token!==load)return;dc=s.exists()?s.data():null;render()},e=>{fail(e)});let first=true;unsub=onSnapshot(query(col(testMode?'testOrders':'orders'),where('date','==',d)),{includeMetadataChanges:true},s=>{if(token!==load)return;const next=s.docs.map(x=>x.data());if(!first&&sound&&d===today()&&next.some(o=>!seen.has(o.id)))beep();seen=new Set(next.map(o=>o.id));first=false;orders=next;$('sync').textContent=s.metadata.fromCache?'Datos guardados anteriormente':s.metadata.hasPendingWrites?'Sincronizando…':'Sincronizado';render()},e=>{$('sync').textContent='Error de sincronización';fail(e)});}
function beep(){try{const c=new (window.AudioContext||window.webkitAudioContext)();const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=660;g.gain.value=.08;o.start();o.stop(c.currentTime+.16);o.onended=()=>c.close()}catch{}}
function setPage(p){stopCamera();main.dataset.page='';page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
function top(title,desc=''){return `<div class="card no-print"><div class="row"><div class="grow"><h2>${esc(title)}</h2><small>${esc(desc)}</small></div><button class="secondary" id="helpPage" aria-label="Ayuda">?</button></div><div class="row"><button class="secondary" id="prev">‹</button><input id="dateSelect" class="grow" type="date" value="${date}"><button class="secondary" id="next">›</button><button class="secondary" id="today">Hoy</button><button class="secondary" id="print">Imprimir</button></div>${testMode?'<p class="bad">MODO PRUEBA · datos separados</p>':''}</div>`}
function wireTop(){if(!$('dateSelect'))return;$('dateSelect').onchange=e=>subscribe(e.target.value||today());$('prev').onclick=()=>subscribe(addDays(date,-1));$('next').onclick=()=>subscribe(addDays(date,1));$('today').onclick=()=>subscribe(today());$('print').onclick=()=>window.print();$('helpPage').onclick=()=>openInfo('Ayuda de '+page,'<p>Selecciona la fecha y los filtros. Los cambios de estado se guardan automáticamente. Comprueba el estado de sincronización antes de entregar.</p>')}
function render(){if(!isAdmin||!master)return;$('nav').hidden=false;$('logout').hidden=false;if(['settings','stats','maintenance','scan','help','calendar'].includes(page)){if(!main.dataset.page||main.dataset.page!==page){main.dataset.page=page;if(page==='settings')settingsPage();if(page==='stats')statsPage();if(page==='maintenance')maintenancePage();if(page==='scan')scanPage();if(page==='help')helpPage();if(page==='calendar')calendarPage()}return}main.dataset.page=page;if(page==='home')home();if(page==='orders'||page==='delivery')ordersPage();if(page==='prep')prepPage();wireTop()}
function home(){const valid=orders.filter(o=>!o.cancelled),un=valid.reduce((s,o)=>s+o.units.length,0),del=orders.reduce((s,o)=>s+Object.keys(o.paid||{}).length,0),prep=valid.reduce((s,o)=>s+o.prepared.length,0);main.innerHTML=top('Resumen diario','Preparación y reparto')+`<section class="card"><h2>${dayLabel(date)}</h2>${metrics([['Pedidos',orders.length],['Unidades activas',un],['Preparadas',prep],['Entregadas',del],['Incidencias',orders.filter(o=>o.incident).length],['Cancelados',orders.filter(o=>o.cancelled).length],['Importe pendiente',money(orders.reduce((s,o)=>s+remaining(o,dc),0))],['Cobrado',money(orders.reduce((s,o)=>s+paidTotal(o),0))]])}<div class="row"><button id="newManual" ${dc?'':'disabled'}>+ Pedido manual</button><button class="secondary" id="goPrep">Preparación</button><button class="secondary" id="goDelivery">Reparto</button><button class="secondary" id="closeDay">Cerrar recreo</button></div>${dc&&date===today()&&Date.now()>=localInstant(date,dc.pickupEnd).getTime()&&orders.some(o=>!o.cancelled&&!o.incident&&Object.keys(o.paid).length<o.units.length)?'<p class="notice warn">Revisa los pedidos pendientes al terminar el recreo.</p>':''}<p class="muted">${dc?dc.open?'Fecha habilitada':'Fecha cerrada':'Fecha sin configuración'}. ${dc?`Recogida ${esc(dc.pickupStart)}–${esc(dc.pickupEnd)}`:''}</p></section>`;$('newManual').onclick=()=>manual();$('goPrep').onclick=()=>setPage('prep');$('goDelivery').onclick=()=>setPage('delivery');$('closeDay').onclick=()=>closeRecess()}
function filtered(){let a=orders.filter(o=>(filters.zone==='all'||o.zone===filters.zone)&&(filters.status==='all'||status(o)===filters.status)&&(filters.product==='all'||o.units.includes(filters.product))&&(filters.course==='all'||o.course===filters.course)&&(filters.group==='all'||o.group===filters.group)&&(filters.prepared==='all'||(filters.prepared==='yes'?o.prepared.length===o.units.length:o.prepared.length<o.units.length))&&(!filters.special||o.notes||o.allergy)&&normal(`${o.name} ${o.surname} ${o.course} ${o.group} ${code(o)}`).includes(normal(filters.q)));return a.sort((a,b)=>filters.sort==='name'?(a.surname+' '+a.name).localeCompare(b.surname+' '+b.name,'es'):filters.sort==='course'?(a.course+a.group).localeCompare(b.course+b.group):filters.sort==='product'?productCompare(sortedUnits(a.units,dc)[0]?.id,sortedUnits(b.units,dc)[0]?.id,dc):a.zone.localeCompare(b.zone)||a.seq-b.seq)}
function ordersPage(){const oldFocus=document.activeElement?.id;const pos=$('search')?.selectionStart;main.innerHTML=top(page==='delivery'?'Modo reparto':'Pedidos','Filtra y localiza rápidamente')+`<div class="card no-print"><div class="row"><button id="newManual" ${dc?'':'disabled'}>+ Pedido manual</button><button id="undo" class="secondary" ${undo?'':'disabled'}>Deshacer última acción</button><button class="secondary" id="closeDay">Cerrar recreo</button></div><label>Zona</label><div class="row">${['all','ESO','CAF'].map(z=>`<button class="${filters.zone===z?'':'secondary'}" data-zone="${z}">${z==='all'?'Todas':z==='ESO'?'Patio ESO':'Cafetería'}</button>`).join('')}</div><label for="search">Buscar alumno, curso o código</label><input id="search" value="${esc(filters.q)}" placeholder="Buscar…"><div class="grid"><div><label>Estado</label><select id="fstatus">${['all','Pendiente','Entrega parcial','Entregado y pagado','Incidencia','Cancelado'].map(x=>opt(x,x==='all'?'Todos':x,filters.status)).join('')}</select></div><div><label>Producto</label><select id="fproduct">${opt('all','Todos',filters.product)}${productOptions(dc,filters.product)}</select></div><div><label>Curso</label><select id="fcourse">${opt('all','Todos',filters.course)}${Object.entries(dc?.courses||{}).map(([id,c])=>opt(id,c.name,filters.course)).join('')}</select></div><div><label>Grupo</label><select id="fgroup">${opt('all','Todos',filters.group)}${[...new Set(Object.values(dc?.courses||{}).flatMap(c=>c.groups))].map(g=>opt(g,g||'Sin grupo',filters.group)).join('')}</select></div><div><label>Preparación</label><select id="fprepared">${[['all','Todos'],['yes','Preparado'],['no','Pendiente']].map(([v,l])=>opt(v,l,filters.prepared)).join('')}</select></div><div><label>Orden</label><select id="fsort">${[['code','Código'],['name','Apellidos'],['course','Curso'],['product','Producto']].map(([v,l])=>opt(v,l,filters.sort)).join('')}</select></div></div><label><input id="fspecial" type="checkbox" ${filters.special?'checked':''}> Solo indicaciones especiales</label></div><div class="card"><div class="row"><h3 class="grow">${dayLabel(date)} · ${filtered().length} pedidos</h3><small>Gris: pendiente · Verde: entregado/pagado · Rojo: incidencia</small></div><div id="orderList">${filtered().map(o=>orderHtml(o)).join('')||'<p>No hay pedidos con estos filtros.</p>'}</div></div>`;const rerender=()=>{const el=$('orderList');el.innerHTML=filtered().map(o=>orderHtml(o)).join('')||'<p>No hay pedidos con estos filtros.</p>';wireOrders()};$('search').oninput=e=>{filters.q=e.target.value;rerender()};for(const [id,k] of [['fstatus','status'],['fproduct','product'],['fcourse','course'],['fgroup','group'],['fprepared','prepared'],['fsort','sort']])$(id).onchange=e=>{filters[k]=e.target.value;rerender()};$('fspecial').onchange=e=>{filters.special=e.target.checked;rerender()};main.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{filters.zone=b.dataset.zone;ordersPage();wireTop()});$('newManual').onclick=()=>manual();$('closeDay').onclick=()=>closeRecess();$('undo').onclick=()=>undoAction();wireOrders();if(oldFocus==='search'){$('search').focus();$('search').setSelectionRange(pos||0,pos||0)}}
function orderHtml(o){const st=status(o),color=o.incident?'red':!o.markerReset&&st==='Entregado y pagado'?'green':'gray';const items=groupedMarkup(sortedUnits(o.units,dc),dc,x=>x.id,({id,i})=>`<div class="row"><span class="grow">${esc(dc?.products[id]?.name||id)} · ${money(priceOf(o,i,dc))}</span><label class="no-print" style="font-size:.85rem"><input type="checkbox" data-prep="${o.id}:${i}" ${o.prepared.includes(i)?'checked':''} ${o.cancelled||Object.hasOwn(o.paid,String(i))?'disabled':''}> Preparado</label><label class="no-print" style="font-size:.85rem"><input type="checkbox" data-pay="${o.id}:${i}" ${Object.hasOwn(o.paid,String(i))?'checked':''} ${o.cancelled?'disabled':''}> Entregado/pagado</label></div>`);return `<article class="order" id="order-${o.id}"><div class="row"><div class="grow"><small>${esc(code(o))} · ${esc(dc?.courses[o.course]?.name||o.course)} ${esc(o.group)} · ${esc(dc?.zones[o.zone]||o.zone)}</small><h3>${esc(o.name+' '+o.surname)}</h3><span class="pill">${esc(st)} · ${Object.keys(o.paid).length}/${o.units.length}</span>${o.version>1?'<span class="pill">Actualizado</span>':''}</div><button class="status ${color} no-print" data-cycle="${o.id}" ${o.cancelled?'disabled':''} title="${esc(o.markerReset?'Marca gris; los cobros se conservan':st)}" aria-label="Cambiar estado">${o.incident?'✕':'✓'}</button></div><div>${items}</div>${o.notes?`<p class="notice warn">Observaciones: ${esc(o.notes)}</p>`:''}${o.allergy?`<p class="notice error no-print">⚠ Indicaciones de alérgenos: ${esc(o.allergy)}</p>`:''}${o.incidentReason?`<p class="bad">${esc(o.incidentReason)}</p>`:''}<div class="row"><b class="grow">Total ${money(total(o,dc))} · Cobrado ${money(paidTotal(o))}</b><button class="secondary no-print" data-edit="${o.id}" ${o.cancelled||Object.keys(o.paid).length?'disabled':''}>Editar</button><button class="secondary no-print" data-incident="${o.id}" ${o.cancelled?'disabled':''}>Incidencia</button><button class="danger no-print" data-cancel="${o.id}" ${o.cancelled||st==='Entregado y pagado'?'disabled':''}>Cancelar</button></div></article>`}
function wireOrders(root=main){root.querySelectorAll('[data-prep]').forEach(el=>el.onchange=()=>{const [id,i]=el.dataset.prep.split(':');changeUnit(id,+i,'prep',el.checked)});root.querySelectorAll('[data-pay]').forEach(el=>el.onchange=()=>{const [id,i]=el.dataset.pay.split(':');changeUnit(id,+i,'pay',el.checked)});root.querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>cycle(b.dataset.cycle));root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>manual(orders.find(o=>o.id===b.dataset.edit)));root.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{const o=orders.find(x=>x.id===b.dataset.incident),reason=prompt('Motivo de incidencia (opcional)',o?.incidentReason||'');if(reason!==null)mutate(b.dataset.incident,x=>({...x,incident:true,incidentReason:reason.slice(0,200)}))});root.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{if(confirm('¿Cancelar las unidades pendientes? Se conservan los cobros previos.'))action(async()=>{if(testMode){await updateDoc(ref('testOrders',b.dataset.cancel),{cancelled:true});return}await saveOrder({reason:'Cafetería'},{existingId:b.dataset.cancel,admin:true,mode:'cancel'});toast('Pedido cancelado')})})}
async function mutate(id,fn){await action(async()=>{const r=ref(testMode?'testOrders':'orders',id);const expected=orders.find(o=>o.id===id)?.version;let before,after;await runTransaction(db,async tx=>{const s=await tx.get(r);if(!s.exists())throw Error('Pedido no encontrado');before=s.data();if(expected!==undefined&&before.version!==expected)throw Error('Otro dispositivo ha modificado el pedido. Actualiza y vuelve a intentar.');const dd=await tx.get(ref('days',before.date));if(dd.data()?.archiving||dd.data()?.archived)throw Error('Fecha archivada');after=fn({...before,units:[...before.units],prepared:[...before.prepared],paid:{...before.paid}},dd.data());after.version=before.version+1;after.updatedAt=serverTimestamp();tx.set(r,after)});undo={id,before,version:before.version+1,collection:testMode?'testOrders':'orders'};toast('Cambio guardado');render()})}
function changeUnit(id,i,kind,on){if(kind==='pay'&&!on&&!confirm('¿Corregir el registro de entrega y cobro de esta unidad?')){render();return}mutate(id,(o,d)=>{if(o.cancelled)throw Error('Pedido cancelado');if(kind==='prep'){if(Object.hasOwn(o.paid,String(i)))return o;o.prepared=on?[...new Set([...o.prepared,i])]:o.prepared.filter(x=>x!==i)}else{if(on){o.markerReset=false;o.paid[i]=priceOf(o,i,d);o.prepared=[...new Set([...o.prepared,i])]}else delete o.paid[i];}return o})}
function cycle(id){const o=orders.find(x=>x.id===id);if(!o)return;const st=status(o);if(o.incident){mutate(id,x=>({...x,incident:false,incidentReason:'',markerReset:true}));return}if(st==='Entregado y pagado'&&o.markerReset){mutate(id,x=>({...x,markerReset:false}));return}if(st==='Entregado y pagado'){mutate(id,x=>({...x,incident:true,incidentReason:'',markerReset:false}));return}if(!confirm('¿Marcar todas las unidades restantes como entregadas y pagadas?'))return;mutate(id,(x,d)=>{x.units.forEach((_,i)=>{if(!Object.hasOwn(x.paid,String(i)))x.paid[i]=priceOf(x,i,d)});x.prepared=x.units.map((_,i)=>i);x.markerReset=false;return x})}
async function undoAction(){if(!undo)return;const u=undo;await action(async()=>{await runTransaction(db,async tx=>{const r=ref(u.collection,u.id),s=await tx.get(r);if(!s.exists())throw Error('Pedido eliminado.');const dd=await tx.get(ref('days',s.data().date));if(!s.exists()||s.data().version!==u.version||dd.data()?.archiving||dd.data()?.archived)throw Error('No se puede deshacer: el pedido ha cambiado o está archivado.');tx.set(r,{...u.before,version:u.version+1,updatedAt:serverTimestamp()})});undo=null;toast('Acción deshecha')})}
function prepPage(){let zones={ESO:{},CAF:{}};for(const o of orders)if(!o.cancelled)o.units.forEach((id,i)=>{const x=zones[o.zone][id]??={total:0,prep:0};x.total++;if(o.prepared.includes(i))x.prep++});const ids=[...new Set([...Object.keys(zones.ESO),...Object.keys(zones.CAF)])].sort((a,b)=>productCompare(a,b,dc));main.innerHTML=top('Preparación','Recuento de unidades por patio')+`<div class="card"><h2>${dayLabel(date)}</h2><label><input id="pendingOnly" type="checkbox"> Mostrar solo pendientes de preparar</label><div class="tablewrap"><table><thead><tr><th>Producto</th><th>ESO total</th><th>ESO pendiente</th><th>CAF total</th><th>CAF pendiente</th><th>Total</th></tr></thead><tbody id="prepRows"></tbody></table></div></div><div class="card"><h3>Indicaciones especiales</h3>${orders.filter(o=>!o.cancelled&&(o.notes||o.allergy)).map(o=>`<div class="notice warn"><b>${esc(code(o))} · ${esc(sortedUnits(o.units,dc).map(({id})=>dc?.products[id]?.name||id).join(', '))}</b><p>${esc(o.notes)}</p>${o.allergy?`<p class="no-print bad">⚠ ${esc(o.allergy)}</p>`:''}</div>`).join('')||'Sin indicaciones especiales'}</div>`;function rows(){const pending=$('pendingOnly').checked;$('prepRows').innerHTML=ids.map(id=>{const a=zones.ESO[id]||{total:0,prep:0},b=zones.CAF[id]||{total:0,prep:0};return pending&&a.total-a.prep+b.total-b.prep===0?'':`<tr><td><small>${esc(productCategory(id,dc))}</small><br>${esc(dc?.products[id]?.name||id)}</td><td>${a.total}</td><td>${a.total-a.prep}</td><td>${b.total}</td><td>${b.total-b.prep}</td><td><b>${a.total+b.total}</b></td></tr>`}).join('')}rows();$('pendingOnly').onchange=rows}
async function closeRecess(){const list=orders.filter(o=>!o.cancelled&&Object.keys(o.paid).length<o.units.length&&!o.incident);if(!list.length){toast('No quedan pedidos pendientes');return}if(!confirm(`¿Marcar ${list.length} pedidos pendientes como incidencia? Los cobros se mantienen.`))return;await action(async()=>{for(const o of list){await runTransaction(db,async tx=>{const r=ref(testMode?'testOrders':'orders',o.id),s=await tx.get(r),v=s.data();if(!v)return;const dd=await tx.get(ref('days',v.date));if(dd.data()?.archiving||dd.data()?.archived)throw Error('Fecha archivada');if(v&&!v.cancelled&&Object.keys(v.paid).length<v.units.length)tx.update(r,{incident:true,incidentReason:'Pendiente al cierre del recreo',updatedAt:serverTimestamp(),version:v.version+1})})}toast('Recreo cerrado')})}
async function manual(old=null){try{const start=old?.date||date,d=await dayRead(start);let items=[...(old?.units||[])],chosen=d;dlg.innerHTML=`<form id="manualForm"><h2>${old?'Editar pedido':'Nuevo pedido manual'}</h2><label>Fecha</label><input id="mdate" type="date" value="${start}" required><div class="grid2"><div><label>Nombre</label><input id="mname" required maxlength="60" value="${esc(old?.name||'')}"></div><div><label>Apellidos</label><input id="msurname" required maxlength="100" value="${esc(old?.surname||'')}"></div></div><label>Curso</label><select id="mcourse"></select><label>Grupo</label><select id="mgroup"></select><label>Zona</label><select id="mzone">${opt('ESO','Patio ESO',old?.zone)}${opt('CAF','Cafetería',old?.zone)}</select><label>Producto</label><div class="row"><select class="grow" id="mproduct"></select><button type="button" id="madd">Añadir</button></div><div id="mitems"></div><label>Observaciones</label><textarea id="mnotes" maxlength="200">${esc(old?.notes||'')}</textarea>${d.allergyEnabled?`<label>Indicaciones de alérgenos</label><textarea id="mallergy" maxlength="200">${esc(old?.allergy||'')}</textarea>`:''}<div class="row"><button type="submit">Guardar</button><button type="button" class="secondary" id="mclose">Cerrar</button></div></form>`;if(!dlg.open)dlg.showModal();function draw(){const c=$('mcourse').value||old?.course;$('mcourse').innerHTML=Object.entries(chosen.courses).filter(([,v])=>v.active).map(([id,v])=>opt(id,v.name,c)).join('');groups(old?.group);$('mproduct').innerHTML=productOptions(chosen,undefined,true);drawItems()}function groups(g){let c=chosen.courses[$('mcourse').value];$('mgroup').innerHTML=(c?.groups||['']).map(x=>opt(x,x||'No procede',g)).join('');$('mzone').value=c?.zone||'CAF'}function drawItems(){$('mitems').innerHTML=groupedMarkup(sortedUnits(items,chosen),chosen,x=>x.id,({id,i})=>`<div class="row"><span class="grow">${esc(chosen.products[id]?.name||id)} · ${money(chosen.products[id]?.price||0)}</span><button type="button" class="secondary" data-rm="${i}">Quitar</button></div>`)+`<b>Total: ${money(items.reduce((s,id)=>s+(chosen.products[id]?.price||0),0))}</b>`;$('mitems').querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.rm,1);drawItems()})}draw();if(old)$('mzone').value=old.zone;$('mcourse').onchange=()=>groups('');$('mdate').onchange=()=>action(async()=>{chosen=await dayRead($('mdate').value);draw()});$('madd').onclick=()=>{if(items.length>=MAX_UNITS){toast('Máximo técnico de 8 unidades por pedido');return}if($('mproduct').value){items.push($('mproduct').value);drawItems()}};$('mclose').onclick=()=>dlg.close();$('manualForm').onsubmit=e=>{e.preventDefault();action(async()=>{if(!items.length)throw Error('Añade productos');const input={date:$('mdate').value,name:textClean($('mname').value),surname:textClean($('msurname').value),course:$('mcourse').value,group:$('mgroup').value,zone:$('mzone').value,units:items,notes:$('mnotes').value,allergy:$('mallergy')?.value||''};if(testMode){const id=old?.id||randomHex(),order={...input,id,owner:ADMIN_UID,seq:orders.length+1,initialPrices:items.map(i=>chosen.products[i].price),prepared:[],paid:{},cancelled:false,incident:false,incidentReason:'',createdAt:old?.createdAt||Timestamp.now(),updatedAt:Timestamp.now(),version:(old?.version||0)+1,test:true};await setDoc(ref('testOrders',id),order);dlg.close();toast('Pedido de prueba guardado');return}const r=await saveOrder(input,{admin:true,existingId:old?.id});dlg.close();openInfo('Pedido guardado',`<p><b>${esc(code(r.order))}</b> · ${dayLabel(r.order.date)}</p>${r.secret?`<p>Contraseña privada: <b>${esc(r.secret)}</b></p><p>Facilítala únicamente al titular.</p>`:''}`)},e.submitter)}}catch(e){fail(e)}}
function stopCamera(){if(frame)cancelAnimationFrame(frame);frame=null;stream?.getTracks().forEach(t=>t.stop());stream=null}
function scanPage(){main.innerHTML='<div class="card"><h2>Escanear QR</h2><p>Escanea el justificante o introduce el código visible y su fecha.</p><video id="video" playsinline muted style="width:100%;max-width:450px" hidden></video><canvas id="scanCanvas" hidden></canvas><div class="row"><button id="camera">Activar cámara</button><button id="stop" class="secondary">Detener</button></div><label>Fecha de recogida</label><input id="scdate" type="date" value="'+date+'"><label>Código visible</label><input id="sccode" placeholder="ESO-001"><button id="findCode">Buscar</button><div id="scanResult"></div></div>';$('camera').onclick=()=>action(async()=>{stopCamera();if(!navigator.mediaDevices?.getUserMedia)throw Error('Cámara no disponible. Usa el código escrito.');if(!window.jsQR&&!('BarcodeDetector'in window))throw Error('Escáner no disponible. Usa el código escrito.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const v=$('video');v.srcObject=stream;v.hidden=false;await v.play();const c=$('scanCanvas'),ctx=c.getContext('2d',{willReadFrequently:true});const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null;async function tick(){if(!stream)return;try{let result;if(v.videoWidth){c.width=v.videoWidth;c.height=v.videoHeight;ctx.drawImage(v,0,0);if(window.jsQR){const d=ctx.getImageData(0,0,c.width,c.height);result=window.jsQR(d.data,d.width,d.height)?.data}else result=(await detector.detect(v))[0]?.rawValue;if(result){stopCamera();await findQR(result);return}}}catch(e){stopCamera();fail(e);return}frame=requestAnimationFrame(tick)}tick()});$('stop').onclick=stopCamera;$('findCode').onclick=()=>action(async()=>{const m=$('sccode').value.trim().toUpperCase().match(/^(ESO|CAF)-(\d+)$/);if(!m)throw Error('Código incorrecto');const s=await getDocs(query(col('orders'),where('date','==',$('scdate').value)));const o=s.docs.map(x=>x.data()).find(x=>x.zone===m[1]&&x.seq===+m[2]);if(!o)throw Error('Pedido no encontrado');await showScanned(o)})}
async function findQR(value){if(!/^TOSTADA:[a-f0-9]{32}$/.test(value))throw Error('QR no válido');await showScanned(await readOrder(value.split(':')[1]))}
async function showScanned(o){await subscribe(o.date);filters={...filters,q:code(o),zone:'all',status:'all',product:'all',course:'all',group:'all',prepared:'all',special:false};setPage('delivery');toast('Pedido localizado: '+code(o))}
function settingsPage(){const b=effective(master,today()),s=b.settings;main.innerHTML=`<div class="card"><h2>Configuración</h2><p>Los cambios operativos se pueden aplicar ahora o programar por fecha de recogida.</p><div class="row"><button id="newProduct">+ Producto</button><button class="secondary" id="newCourse">+ Curso</button><button class="secondary" id="newCategory">+ Categoría</button></div></div><div class="card"><h2>Productos</h2><div class="tablewrap"><table><thead><tr><th>Producto</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody>${sortedProducts(b).map(([id,p])=>`<tr><td>${esc(p.name)}<br><small>${esc(p.category)} · ${p.verified?'Alérgenos revisados':'Sin verificar'}</small></td><td>${money(p.price)}</td><td>${p.active?'Activo':'Desactivado'}</td><td><button class="secondary" data-product="${esc(id)}">Editar</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Horarios y límites</h2><form id="settingsForm"><div class="grid">${[['limitUser','Unidades por alumno','number',1,8],['advance','Días de antelación','number',0,30],['limitDay','Límite total (0 = ilimitado)','number',0,10000],['limitESO','Límite patio ESO','number',0,10000],['limitCAF','Límite cafetería','number',0,10000],['editMinutes','Minutos para modificar','number',1,120],['cutoff','Cierre pedidos','time'],['editCutoff','Cierre modificaciones','time'],['pickupStart','Inicio recreo','time'],['pickupEnd','Fin recreo','time']].map(([k,n,t,min,max])=>`<div><label>${n}</label><input name="${k}" type="${t}" ${t==='number'?`min="${min}" max="${max}" step="1"`:''} required value="${esc(s[k])}"></div>`).join('')}</div><label><input name="weekend" type="checkbox" ${s.weekend?'checked':''}> Recogidas en fin de semana</label><label><input name="enabled" type="checkbox" ${s.enabled?'checked':''}> Pedidos abiertos según calendario</label><label><input name="allergyEnabled" type="checkbox" ${s.allergyEnabled?'checked':''}> Activar campo de intolerancias (solo con autorización de privacidad)</label><label>Aviso general</label><textarea name="announcement" maxlength="300">${esc(s.announcement)}</textarea><button>Guardar horarios y límites</button></form></div><div class="card"><h2>Cursos y zonas</h2>${Object.entries(b.courses).map(([id,c])=>`<div class="product"><span class="grow">${esc(c.name)} · ${esc(c.groups.join(', ')||'Único')} · ${esc(b.zones[c.zone])}${c.active?'':' · Desactivado'}</span><button class="secondary" data-course="${esc(id)}">Editar</button></div>`).join('')}<button class="secondary" id="editZones">Editar nombres de zonas</button></div><div class="card"><h2>Cambios programados e historial</h2>${(master.changes||[]).slice().reverse().map(c=>`<div class="row product"><span class="grow">${dayLabel(c.date)} · ${esc(c.label||'Cambio')}<br><small>${c.date>today()?'Pendiente':'En vigor/histórico'}</small></span>${c.date>today()?`<button class="danger" data-removechange="${esc(c.id)}">Cancelar cambio</button>`:''}</div>`).join('')||'<p>Sin cambios registrados.</p>'}</div><div class="card"><h2>Acceso y opciones locales</h2><button id="changeCode">Cambiar código del alumnado</button><label><input id="sound" type="checkbox" ${sound?'checked':''}> Aviso sonoro de nuevos pedidos</label><label><input id="testMode" type="checkbox" ${testMode?'checked':''}> Modo prueba (datos separados)</label></div>`;$('newProduct').onclick=()=>productDialog();$('newCourse').onclick=()=>courseDialog();$('newCategory').onclick=()=>{const n=prompt('Nombre de la categoría');if(n?.trim()&&!b.categories.includes(n.trim()))schedule({categories:[...b.categories,n.trim()]},'Nueva categoría '+n.trim())};main.querySelectorAll('[data-product]').forEach(x=>x.onclick=()=>productDialog(x.dataset.product));main.querySelectorAll('[data-course]').forEach(x=>x.onclick=()=>courseDialog(x.dataset.course));$('settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={};for(const k of ['limitUser','advance','limitDay','limitESO','limitCAF','editMinutes'])v[k]=Number(f.get(k));for(const k of ['cutoff','editCutoff','pickupStart','pickupEnd','announcement'])v[k]=String(f.get(k));for(const k of ['weekend','enabled','allergyEnabled'])v[k]=f.has(k);if(v.editCutoff>v.cutoff||v.cutoff>v.pickupStart||v.pickupStart>=v.pickupEnd){toast('Revisa el orden de horarios');return}if(v.allergyEnabled&&!s.allergyEnabled&&!confirm('Confirma que el responsable de protección de datos ha autorizado el tratamiento de información sanitaria.'))return;const patch=Object.fromEntries(Object.entries(v).filter(([k,x])=>x!==s[k]));if(!Object.keys(patch).length){toast('Sin cambios');return}schedule({settings:patch},'Horarios y límites')};$('editZones').onclick=()=>{const a=prompt('Nombre de la zona ESO',b.zones.ESO),c=prompt('Nombre de la zona cafetería',b.zones.CAF);if(a?.trim()&&c?.trim())schedule({zones:{ESO:a.trim(),CAF:c.trim()}},'Nombres de zonas')};$('changeCode').onclick=()=>{const x=prompt('Nuevo código común (mínimo 10 caracteres)');if(x?.trim().length>=10)action(async()=>{await setDoc(ref('config','private'),{hash:await sha(x.trim())});toast('Código cambiado. El alumnado deberá volver a validarlo.')})};$('sound').onchange=e=>{sound=e.target.checked;localStorage.setItem('tostada.sound',sound?'1':'0');if(sound)beep()};$('testMode').onchange=e=>{testMode=e.target.checked;subscribe(date);setPage('home')};main.querySelectorAll('[data-removechange]').forEach(b=>b.onclick=()=>{if(confirm('¿Cancelar este cambio programado?'))action(async()=>{await updateMaster(m=>({...m,changes:m.changes.filter(c=>c.id!==b.dataset.removechange)}));settingsPage();toast('Cambio cancelado')})})}
async function updateMaster(fn){await runTransaction(db,async tx=>{const r=ref('config','main'),s=await tx.get(r);const v=s.data(),next=fn(v);next.revision=v.revision+1;const from=today(),dates=Array.from({length:32},(_,i)=>addDays(from,i)),existing=[];for(const d of dates)existing.push(await tx.get(ref('days',d)));const availability=[];tx.set(r,next);for(let i=0;i<dates.length;i++){const old=existing[i].data();if(old?.archived||old?.archiving)continue;const conf=dayConfig(next,dates[i]);tx.set(ref('days',dates[i]),conf,{merge:true});if(conf.open)availability.push({date:dates[i],opensAt:conf.opensAt,cutoffAt:conf.cutoffAt,editAt:conf.editAt});}tx.set(ref('system','status'),{ready:true,revision:next.revision,minVersion:VERSION,publishedFor:from,available:availability,advance:effective(next,from).settings.advance,updatedAt:serverTimestamp()});tx.set(ref('system','access'),{ready:true});master=next});}
function schedule(patch,label){if(dlg.open)dlg.close();dlg.innerHTML=`<form id="scheduleForm"><h2>Confirmar cambio</h2><p>${esc(label)}</p><label><input type="radio" name="when" value="now" checked> Aplicar ahora</label><label><input type="radio" name="when" value="date"> Programar fecha</label><input type="date" id="effectiveDate" min="${today()}" value="${today()}"><p class="notice">El precio de unidades pendientes se actualizará según la fecha de recogida. Las unidades cobradas mantienen su importe.</p><div class="row"><button>Confirmar</button><button type="button" class="secondary" id="scCancel">Cancelar</button></div></form>`;if(!dlg.open)dlg.showModal();$('scCancel').onclick=()=>dlg.close();$('scheduleForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=new FormData(e.target),d=f.get('when')==='now'?today():$('effectiveDate').value;if(!d||d<today())throw Error('Fecha no válida');await updateMaster(m=>({...m,changes:[...(m.changes||[]),{id:Date.now().toString().padStart(15,'0')+'-'+randomHex(4),date:d,label,patch}]}));dlg.close();main.dataset.page='';render();toast('Configuración guardada')},e.submitter)}}
function productDialog(id=null){const b=effective(master,today()),p=b.products[id]||{name:'',category:b.categories[0],price:100,description:'',active:true,verified:false,allergens:[],traces:[],limit:0};dlg.innerHTML=`<form id="productForm"><h2>${id?'Editar producto':'Añadir producto'}</h2><label>Nombre</label><input name="name" required maxlength="80" value="${esc(p.name)}"><label>Categoría</label><select name="category">${b.categories.map(c=>opt(c,c,p.category)).join('')}</select><label>Precio (€)</label><input name="price" type="number" required min="0.01" max="100" step="0.01" value="${(p.price/100).toFixed(2)}"><label>Descripción</label><textarea name="description" maxlength="200">${esc(p.description)}</textarea><label>Máximo diario (0 = sin límite)</label><input name="limit" type="number" min="0" max="10000" step="1" value="${p.limit||0}" required><label><input name="active" type="checkbox" ${p.active?'checked':''}> Disponible para nuevos pedidos</label><label><input name="verified" type="checkbox" ${p.verified?'checked':''}> Información de alérgenos verificada por cafetería</label><div class="tablewrap"><table><thead><tr><th>Alérgeno</th><th>Contiene</th><th>Trazas</th></tr></thead><tbody>${ALLERGENS.map((a,i)=>`<tr><td>${esc(a)}</td><td><input type="checkbox" name="a${i}" ${p.allergens.includes(a)?'checked':''} aria-label="Contiene ${esc(a)}"></td><td><input type="checkbox" name="t${i}" ${p.traces.includes(a)?'checked':''} aria-label="Trazas de ${esc(a)}"></td></tr>`).join('')}</tbody></table></div><div class="row"><button>Guardar</button><button type="button" id="pClose" class="secondary">Cerrar</button>${id?'<button type="button" id="pRemove" class="danger">Retirar del catálogo</button>':''}</div></form>`;if(!dlg.open)dlg.showModal();$('pClose').onclick=()=>dlg.close();if(id)$('pRemove').onclick=()=>{if(confirm('Los pedidos existentes se conservarán. ¿Retirar producto?'))schedule({products:{[id]:{active:false}}},'Retirar '+p.name)};$('productForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={name:textClean(f.get('name')),category:f.get('category'),price:Math.round(Number(f.get('price'))*100),description:String(f.get('description')).trim(),active:f.has('active'),limit:Number(f.get('limit')),verified:f.has('verified'),allergens:ALLERGENS.filter((_,i)=>f.has('a'+i)),traces:ALLERGENS.filter((_,i)=>f.has('t'+i))};if(!v.name||!v.price){toast('Revisa los datos');return}const diff=id?Object.fromEntries(Object.entries(v).filter(([k,x])=>JSON.stringify(x)!==JSON.stringify(p[k]))):v;if(!Object.keys(diff).length){dlg.close();return}schedule({products:{[id||'P'+randomHex(5)]:diff}},'Producto: '+v.name)}}
function courseDialog(id=null){const b=effective(master,today()),c=b.courses[id]||{name:'',groups:[''],zone:'CAF',active:true};dlg.innerHTML=`<form id="courseForm"><h2>${id?'Editar curso':'Nuevo curso'}</h2><label>Nombre</label><input name="name" required maxlength="60" value="${esc(c.name)}"><label>Grupos separados por comas (vacío = único)</label><input name="groups" maxlength="80" value="${esc(c.groups.join(','))}"><label>Zona de recogida</label><select name="zone">${Object.entries(b.zones).map(([k,n])=>opt(k,n,c.zone)).join('')}</select><label><input type="checkbox" name="active" ${c.active?'checked':''}> Activo</label><div class="row"><button>Guardar</button><button type="button" id="cclose" class="secondary">Cerrar</button></div></form>`;if(!dlg.open)dlg.showModal();$('cclose').onclick=()=>dlg.close();$('courseForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={name:textClean(f.get('name')),groups:[...new Set(String(f.get('groups')).split(',').map(x=>x.trim().toUpperCase()).filter(Boolean))],zone:f.get('zone'),active:f.has('active')};if(!v.groups.length)v.groups=[''];schedule({courses:{[id||'C'+randomHex(5)]:v}},'Curso: '+v.name)}}
async function calendarPage(){main.innerHTML=`<div class="card"><h2>Calendario</h2><p>Al cerrar un día se cancelan las unidades no entregadas, conservando los cobros.</p><label>Fecha</label><input id="calDate" type="date" min="${today()}" value="${today()}"><div class="row"><button id="block" class="danger">Cerrar día</button><button id="unblock" class="secondary">Reabrir día</button><button id="viewDate" class="secondary">Ver pedidos</button></div><div id="calRows"></div></div>`;const b=effective(master,today());$('calRows').innerHTML=`<h3>Días bloqueados</h3>${Object.entries(b.closed).filter(([,v])=>v).map(([d])=>`<p>${dayLabel(d)}</p>`).join('')||'Ninguno'}`;$('viewDate').onclick=()=>{subscribe($('calDate').value);setPage('orders')};$('block').onclick=()=>action(async()=>{const d=$('calDate').value;if(!d||d<today())throw Error('Fecha inválida');const q=await getDocs(query(col('orders'),where('date','==',d)));const affected=q.docs.map(x=>x.data()).filter(o=>!o.cancelled&&Object.keys(o.paid).length<o.units.length);if(!confirm(`Cerrar ${dayLabel(d)} y cancelar ${affected.length} pedidos pendientes?`))return;await updateMaster(m=>({...m,base:merge(m.base,{closed:{[d]:true}})}));const after=await getDocs(query(col('orders'),where('date','==',d)));for(const o of after.docs.map(x=>x.data()).filter(o=>!o.cancelled&&Object.keys(o.paid).length<o.units.length))await saveOrder({reason:'Día cerrado por cafetería'},{existingId:o.id,admin:true,mode:'cancel'});toast('Día cerrado');calendarPage()});$('unblock').onclick=()=>action(async()=>{const d=$('calDate').value;if(!confirm('¿Reabrir? Los pedidos cancelados no se restauran.'))return;await updateMaster(m=>({...m,base:merge(m.base,{closed:{[d]:false}})}));toast('Calendario actualizado');calendarPage()})}
async function statsPage(){main.innerHTML=`<div class="card"><h2>Estadísticas</h2><p>Unidades solicitadas y entregadas, por fecha, producto y zona. Incluye pedidos recientes y resúmenes archivados.</p><div class="grid2"><div><label>Desde</label><input id="sfrom" type="date" value="${addDays(today(),-30)}"></div><div><label>Hasta</label><input id="sto" type="date" value="${today()}"></div></div><div class="row"><button id="sload">Consultar</button><button id="sexport" class="secondary" disabled>Exportar CSV (Excel)</button></div><div id="stats"></div></div>`;let rows=[];const run=async()=>{const a=$('sfrom').value,b=$('sto').value;if(!a||!b||a>b)throw Error('Rango no válido');const s=await getDocs(query(col('statistics'),where('date','>=',a),where('date','<=',b)));const summaries=new Map(s.docs.map(x=>[x.id,x.data()]));const live=await getDocsFromServer(query(col('orders'),where('date','>=',a),where('date','<=',b)));const byDay=new Map();for(const x of live.docs){const o=x.data();if(!summaries.has(o.date)){if(!byDay.has(o.date))byDay.set(o.date,[]);byDay.get(o.date).push(o)}}for(const [d,items] of byDay){const ds=await getDocFromServer(ref('days',d));summaries.set(d,aggregate(items,ds.data()?.products))}const catalogue=effective(master,today());rows=[...summaries].sort(([x],[y])=>x.localeCompare(y)).flatMap(([d,v])=>Object.entries(v.zones||{}).flatMap(([z,ps])=>Object.entries(ps).sort(([a],[b])=>productCompare(a,b,catalogue)).map(([id,p])=>[d,z,p.name||id,p.requested,p.delivered,productCategory(id,catalogue),id])));const totals={};for(const r of rows){const k=r[6],p=totals[k]??=[0,0,r[2]];p[0]+=r[3];p[1]+=r[4]}const sum=rows.reduce((n,r)=>[n[0]+r[3],n[1]+r[4]],[0,0]);const max=Math.max(1,...Object.values(totals).map(x=>x[0]));$('stats').innerHTML=metrics([['Solicitadas',sum[0]],['Entregadas',sum[1]]])+`<h3>Demanda por producto</h3>${groupedMarkup(Object.entries(totals).sort(([a],[b])=>productCompare(a,b,catalogue)),catalogue,x=>x[0],([k,v])=>`<p>${esc(catalogue.products[k]?.name||v[2])} · ${v[0]} / ${v[1]}<br><progress max="${max}" value="${v[0]}" style="width:100%"></progress></p>`)}<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Zona</th><th>Categoría</th><th>Producto</th><th>Solicitadas</th><th>Entregadas</th></tr></thead><tbody>${rows.map(r=>`<tr>${[r[0],r[1],r[5],r[2],r[3],r[4]].map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small>El histórico permanente incluye días archivados. Los días recientes se consultan en Pedidos.</small>`;$('sexport').disabled=!rows.length};$('sload').onclick=()=>action(run,$('sload'));$('sexport').onclick=()=>{const blob=new Blob([csv([['Fecha','Zona','Categoría','Producto','Solicitadas','Entregadas'],...rows.map(r=>[r[0],r[1],r[5],r[2],r[3],r[4]])])],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='estadisticas-tostadas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};action(run)}
async function archiveDate(d){const dayref=ref('days',d);await runTransaction(db,async tx=>{const s=await tx.get(dayref);if(!s.exists()||s.data().archived)return;tx.update(dayref,{archiving:true,open:false})});const ds=await getDocFromServer(dayref);if(!ds.exists()||ds.data().archived)return;const sr=ref('statistics',d);let st=await getDocFromServer(sr);if(!st.exists()){const q=await getDocsFromServer(query(col('orders'),where('date','==',d)));const summary=aggregate(q.docs.map(x=>x.data()),ds.data().products);await runTransaction(db,async tx=>{const s=await tx.get(sr);if(!s.exists())tx.set(sr,{date:d,...summary,archivedAt:serverTimestamp()})});st=await getDocFromServer(sr)}if(!st.exists()||!validSummary(st.data(),d))throw Error('Resumen inconsistente; no se borrará ningún pedido.');const q=await getDocsFromServer(query(col('orders'),where('date','==',d)));for(const x of q.docs){const p=await getDocFromServer(ref('privateOrders',x.id));const grants=await getDocsFromServer(col('orders',x.id,'grants'));for(let i=0;i<grants.docs.length;i+=400){const b=writeBatch(db);grants.docs.slice(i,i+400).forEach(g=>b.delete(g.ref));await b.commit()}const b=writeBatch(db);if(p.exists())b.delete(ref('recovery',p.data().hash));b.delete(ref('privateOrders',x.id));b.delete(x.ref);await b.commit()}const lim=await getDocsFromServer(query(col('limits'),where(documentId(),'>=',d+'_'),where(documentId(),'<=',d+'_\uf8ff')));for(let i=0;i<lim.docs.length;i+=400){const b=writeBatch(db);lim.docs.slice(i,i+400).filter(x=>x.id.startsWith(d+'_')).forEach(x=>b.delete(x.ref));await b.commit()}await deleteDoc(ref('daily',d));await updateDoc(dayref,{archived:true,archiving:false,open:false});}
async function maintenance(manual=true){if(working||testMode)return;working=true;try{online();const until=addDays(today(),-15);const cfg=effective(master,addDays(today(),31));for(const [d,closed] of Object.entries(cfg.closed||{})){if(!closed||d<=until||d>addDays(today(),31))continue;const ds=await getDocFromServer(ref('days',d));if(!ds.exists()||ds.data().open||ds.data().archived||ds.data().archiving)continue;const q=await getDocsFromServer(query(col('orders'),where('date','==',d)));for(const o of q.docs.map(x=>x.data()).filter(o=>!o.cancelled&&Object.keys(o.paid).length<o.units.length))await saveOrder({reason:'Día cerrado por cafetería'},{existingId:o.id,admin:true,mode:'cancel'});}const days=await getDocsFromServer(query(col('days'),where('date','<=',until)));const pending=days.docs.filter(d=>!d.data().archived);for(const d of pending)await archiveDate(d.id);const tests=await getDocsFromServer(query(col('testOrders'),where('date','<=',until)));for(const x of tests.docs)await deleteDoc(x.ref);await setDoc(ref('maintenance','last'),{at:serverTimestamp(),result:'ok',dates:pending.length},{merge:true});if(manual)toast('Mantenimiento completado: '+pending.length+' fechas')}catch(e){if(manual)fail(e);try{await setDoc(ref('maintenance','last'),{at:serverTimestamp(),result:'error'},{merge:true})}catch{}}finally{working=false;if(page==='maintenance')maintenancePage()}}
async function maintenancePage(){main.innerHTML=`<div class="card"><h2>Mantenimiento</h2><p id="mstat">Consultando…</p><button id="mrun">Ejecutar mantenimiento</button><p class="notice">Se guardan los resúmenes antes de eliminar los datos de pedidos antiguos. Puedes consultar la última ejecución o iniciar el mantenimiento manualmente.</p></div>`;$('mrun').onclick=()=>{if(confirm('¿Ejecutar el archivado de fechas vencidas? Esta operación elimina datos personales tras guardar los resúmenes.'))maintenance(true)};try{const s=await getDocFromServer(ref('maintenance','last'));if($('mstat'))$('mstat').textContent=s.exists()?`Última ejecución: ${s.data().at?.toDate().toLocaleString('es-ES')} · ${s.data().result==='ok'?'Completado':'Pendiente de revisión'} · fechas: ${s.data().dates??'—'}`:'No hay mantenimiento registrado.'}catch(e){if($('mstat'))$('mstat').textContent=describe(e)}}
function helpPage(){main.innerHTML=`<div class="card"><h2>Ayuda de cafetería</h2><details open><summary>Pedidos y reparto</summary><p>Selecciona fecha y filtros. Marca cada unidad preparada o entregada/pagada. El tic general pasa de gris a verde a rojo a gris. Al reiniciar la marca se conservan los cobros de las unidades entregadas, y el estado textual refleja la realidad. Corrige entregas individualmente o deshaz la última acción si nadie ha modificado el pedido.</p></details><details><summary>Preparación</summary><p>Consulta cantidades por producto y patio. Imprime el resumen sin datos sanitarios. Las observaciones aparecen destacadas.</p></details><details><summary>Precios y catálogo</summary><p>Los precios vigentes dependen de la fecha de recogida. Retirar un producto bloquea nuevos pedidos sin eliminar los existentes. Los cambios programados aparecen en Configuración.</p></details><details><summary>Calendario y mantenimiento</summary><p>Bloquear una fecha cancela pendientes. A los 15 días se archiva el resumen y se borran datos personales. Consulta el resultado en Mantenimiento.</p></details><details><summary>Seguridad</summary><p>No compartas la contraseña administrativa fuera del personal autorizado. Usa pedidos de prueba para ensayar. El código común no verifica la identidad individual.</p></details><details><summary>Instalar aplicación</summary><p>Menú del navegador → Instalar aplicación o Añadir a pantalla de inicio.</p></details></div>`}
$('theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('tostada.adminTheme',document.body.classList.contains('dark')?'1':'0')};document.body.classList.toggle('dark',localStorage.getItem('tostada.adminTheme')==='1');$('logout').onclick=()=>{cleanup();signOut(auth)};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{main.dataset.page='';setPage(b.dataset.page)});const connection=()=>{$('offline').hidden=navigator.onLine;if(!navigator.onLine)$('sync').textContent='Sin conexión'};addEventListener('online',connection);addEventListener('offline',connection);connection();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});boot();
